/**
 * Shared between the `backlinks` and `graph` plugin forks so Base pages collapse
 * out of both consistently. Pure data transform, no Node APIs — safe to bundle
 * into a browser script (imported by graph's client-side inline script).
 */

export interface Edge {
  source: string;
  target: string;
}

/** A Base virtual page (e.g. Obsidian `.base` files) keeps its extension in its slug. */
export function isBaseSlug(slug: string): boolean {
  return slug.endsWith(".base");
}

/**
 * Collapses any path `A -> B -> C` where `B` is collapsible (e.g. a Base) into a
 * direct edge `A -> C`, transitively through chains of collapsible nodes, and
 * drops every edge that still touches a collapsible node. Cycle-safe.
 */
export function collapseThroughBases(
  edges: Edge[],
  isCollapsible: (slug: string) => boolean = isBaseSlug,
): Edge[] {
  const outgoing = new Map<string, Set<string>>();
  for (const { source, target } of edges) {
    let targets = outgoing.get(source);
    if (!targets) {
      targets = new Set();
      outgoing.set(source, targets);
    }
    targets.add(target);
  }

  function expand(node: string, visited: Set<string>): Set<string> {
    if (!isCollapsible(node)) return new Set([node]);
    if (visited.has(node)) return new Set();
    visited.add(node);
    const result = new Set<string>();
    for (const next of outgoing.get(node) ?? []) {
      for (const t of expand(next, visited)) result.add(t);
    }
    return result;
  }

  const result: Edge[] = [];
  const seen = new Set<string>();
  for (const { source, target } of edges) {
    if (isCollapsible(source)) continue;
    for (const t of expand(target, new Set())) {
      if (source === t) continue;
      const key = source + "�" + t;
      if (seen.has(key)) continue;
      seen.add(key);
      result.push({ source, target: t });
    }
  }
  return result;
}
